&reftitle.returnvalues;


 Restituisce FTP_FAILED o FTP_FINISHED
 o FTP_MOREDATA, oppure &false; se non è possibile aprire il file locale.

&reftitle.changelog;





    &Version;
    &Description;



   &ftp.changelog.ftp-param;
   &ext.ftp.changelog.mode-valueerror;


    7.3.0

     Il parametro mode ora è opzionale. In precedenza
     era obbligatorio.

  &reftitle.examples;



    Esempio di ftp_nb_get


<?php

// Avvia lo scaricamento
$ret = ftp_nb_get($ftp, "test", "README", FTP_BINARY);
while ($ret == FTP_MOREDATA) {

   // Fare qualsiasi altra operazione
   echo ".";

   // Continua lo scaricamento...
   $ret = ftp_nb_continue($ftp);
}
if ($ret != FTP_FINISHED) {
   echo "Si è verificato un errore durante lo scaricamento del file...";
   exit(1);
}
?>




    Ripresa di uno scaricamento con ftp_nb_get


<?php

// Avvio
$ret = ftp_nb_get($ftp, "test", "README", FTP_BINARY, 
                      filesize("test"));
// OPPURE: $ret = ftp_nb_get($ftp, "test", "README",
//                           FTP_BINARY, FTP_AUTORESUME);
while ($ret == FTP_MOREDATA) {

   // Fare qualsiasi altra operazione
   echo ".";

   // Continua lo scaricamento...
   $ret = ftp_nb_continue($ftp);
}
if ($ret != FTP_FINISHED) {
   echo "Si è verificato un errore durante lo scaricamento del file...";
   exit(1);
}
?>





     Ripresa di uno scaricamento dalla posizione 100 in un nuovo
     file con ftp_nb_get



<?php

// Disabilita Autoseek
ftp_set_option($ftp, FTP_AUTOSEEK, false);

// Avvio
$ret = ftp_nb_get($ftp, "newfile", "README", FTP_BINARY, 100);
while ($ret == FTP_MOREDATA) {

   /* ... */

   // Continua lo scaricamento...
   $ret = ftp_nb_continue($ftp);
}
?>






   Nell'esempio precedente, newfile è più piccolo di 100 byte
   rispetto a README sul server FTP perché la lettura è iniziata
   dall'offset 100. Se non si fosse disabilitato
   FTP_AUTOSEEK, i primi 100 byte di
   newfile sarebbero stati '\0'.
